using System;using System.IO;using System.Linq;using System.Text;
namespace NcnHelper {
public static class Turbo {
 public static readonly string Prompt="## Fast live dialogue — final delivery override\nThis overrides long-monologue and minimum-length instructions in other style presets. Give ONE compact turn of 1-2 natural spoken sentences, about 10-35 words total. Start with a short reaction of 2-7 words ending in punctuation so speech can begin early. Then, only if useful, give one sharper follow-up. Keep aggression, profanity, character voice and the selected language. Finish naturally. A question, taunt or challenge is optional, never an obligatory ending. A complete statement is a valid way to finish. No explanation of the joke, recap, long narration, polite closing, invented answer from V or next NPC turn. If the Ukrainian chaos preset requires a TCC/front threat after V's provocation, fit that threat into these same short sentences; do not add a monologue. Preserve [EMOTION: ...], [TO: ...] when needed, and the final [ACTION: ...] tag required by the engine.\nОстаточна вимога темпу: зараз лише 1-2 живі фрази, максимум близько 35 слів, навіть якщо вище написано 5-7 речень. Коротко огризнися, підколупни або кинь виклик і віддай слово Ві. Запитання або виклик необов’язкові; можна просто завершити думку. Не розжовуй і не дописуй його реакцію. Усі службові теги збережи.\n";
 public static void Build(Plan p,int mode){if(mode==0)return;foreach(string name in new[]{"settings.tpl","system.tpl"}){string file=Path.Combine(Core.Mod(p.Game),@"data\templates",name);if(!File.Exists(file))continue;var existing=p.Changes.FirstOrDefault(x=>String.Equals(x.Target,file,StringComparison.OrdinalIgnoreCase));string text=existing==null?File.ReadAllText(file):Encoding.UTF8.GetString(existing.Bytes).TrimStart((char)0xfeff);string delivery=Prompt;if(text.Contains("UKRAINIAN CHAOS PRESET"))delivery+="\nДля агресивного UA/RU режиму: у кожній репліці вживи 1-3 справді жорсткі матюки зі словника, без зірочок і пом’якшення. Наприклад: блядь, курва, нахуй, довбойоб, пиздець. Якщо Ві щойно образив тебе, в цих самих 1-2 фразах неодмінно згадай погрозу здати Ві до ТЦК або відправити його на фронт. Питання чи виклик необов’язкові; заверши репліку природно. Міняй слова й формулювання, не цитуй один приклад щоразу.\n";byte[] bytes=Core.Encode(Core.Overlay(text,"SPEED",mode==1?delivery:""),file);if(existing==null)Core.Add(p,file,bytes,null);else{existing.Bytes=bytes;existing.AfterHash=existing.HashNew();}}p.Summary.Add(mode==1?"Fast dialogue: 1-2 sentences, a quick opening, then V can respond.":"Removed only the helper fast-dialogue prompt.");}
}
}
